let paginaAnterior = 0;

try {
  paginaAnterior = $('Proxima pagina').last().json.page;
} catch (e) {
  paginaAnterior = 0;
}

return [
  {
    json: {
      page: paginaAnterior + 1
    }
  }
];

/* =========================================================
   PULA BOLETO JA FECHADO

   O que faz a execucao demorar e o detalhe: e uma chamada
   HTTP por boleto. Boleto pago nao muda mais, entao nao
   precisa ser buscado nem regravado todo dia.

   So fica de fora quem cumpre as tres condicoes:
     1. ja consta como pago na planilha;
     2. a Cora continua devolvendo o mesmo status na
        listagem (se mudou, passa e atualiza);
     3. o Nome da Cobranca ja foi gravado na linha.

   A condicao 3 deixa o historico antigo terminar de ser
   preenchido uma vez antes de a linha ser congelada.
========================================================= */

// Para tratar cancelado do mesmo jeito, use ['PAID', 'CANCELLED'].
const STATUS_FINAIS = ['PAID'];

const registroPorId = new Map();

for (const item of $('Ler TodosBoletos uma vez').all()) {
  const registro = item.json || {};
  const id = String(registro.id || '').trim();

  if (id) {
    registroPorId.set(id, registro);
  }
}

const precisaAtualizar = boleto => {
  const id = String(boleto.id || '').trim();

  if (!id) {
    return false;
  }

  const registro = registroPorId.get(id);

  // Boleto que ainda nao esta na planilha sempre entra.
  if (!registro) {
    return true;
  }

  const statusNaPlanilha = String(registro.status || '')
    .trim()
    .toUpperCase();

  if (!STATUS_FINAIS.includes(statusNaPlanilha)) {
    return true;
  }

  // A listagem ja traz o status atual da Cora: se ele
  // divergir do que esta na planilha, algo mudou no boleto
  // e a linha precisa ser refeita.
  const statusNaCora = String(boleto.status || '')
    .trim()
    .toUpperCase();

  if (statusNaCora && statusNaCora !== statusNaPlanilha) {
    return true;
  }

  const nomeNaPlanilha = String(
    registro['Nome da Cobrança'] || ''
  ).trim();

  return nomeNaPlanilha === '';
};

const saida = [];

$input.all().forEach((item, index) => {
  if (precisaAtualizar(item.json || {})) {
    saida.push({
      json: item.json,
      pairedItem: { item: index },
    });
  }
});

return saida;

const entradasDetalhes = $input.all();

/* =========================================================
   RESUMO DA LISTAGEM, POR ID

   Antes o resumo vinha de itemMatching(index). Com o filtro
   de boletos fechados no meio do caminho, casar por posicao
   fica fragil: casamos por id, que e o que de fato liga a
   listagem ao detalhe.
========================================================= */

const resumoPorId = new Map();

for (const item of $('Boletos a atualizar').all()) {
  const resumo = item.json || {};
  const id = String(resumo.id || '').trim();

  if (id) {
    resumoPorId.set(id, resumo);
  }
}

const itens = entradasDetalhes.map(item => {
  const detalhes = item.json || {};

  const resumo =
    resumoPorId.get(String(detalhes.id || '').trim()) || {};

  // Une os dados da listagem com os detalhes.
  const boletoCompleto = {
    ...resumo,
    ...detalhes,
  };

  // Se o detalhe trouxe campo vazio, preserva o valor da listagem.
  const camposDaListagem = [
    'status',
    'created_at',
    'total_amount',
    'customer_name',
    'customer_document',
    'due_date',
    'payment_form',
    'paid_at',
    'total_paid',
    'fine_paid',
    'interest_paid',
    'discount_paid',
  ];

  for (const campo of camposDaListagem) {
    const valorDetalhe = detalhes[campo];
    const valorResumo = resumo[campo];

    if (
      (
        valorDetalhe === null ||
        valorDetalhe === undefined ||
        valorDetalhe === ''
      ) &&
      valorResumo !== null &&
      valorResumo !== undefined &&
      valorResumo !== ''
    ) {
      boletoCompleto[campo] = valorResumo;
    }
  }

  // Preserva as estruturas completas necessárias para o link.
  boletoCompleto.payment_options =
    detalhes.payment_options ||
    resumo.payment_options ||
    {};

  boletoCompleto.payment_terms =
    detalhes.payment_terms ||
    resumo.payment_terms ||
    {};

  boletoCompleto.services =
    detalhes.services ||
    resumo.services ||
    [];

  return boletoCompleto;
});

const linhasAtuais = $('Ler TodosBoletos uma vez').all();

/* =========================================================
   MAPA: ID DO BOLETO → NÚMERO DA LINHA
========================================================= */

const linhaPorId = new Map();

for (let i = 0; i < linhasAtuais.length; i++) {
  const registro = linhasAtuais[i].json || {};
  const id = String(registro.id || '').trim();

  if (id) {
    linhaPorId.set(
      id,
      Number(registro.row_number) || i + 2
    );
  }
}

/* =========================================================
   FUNÇÕES AUXILIARES
========================================================= */

const primeiroValor = (...valores) => {
  for (const valor of valores) {
    if (
      valor !== null &&
      valor !== undefined &&
      valor !== ''
    ) {
      return valor;
    }
  }

  return '';
};

const texto = valor => {
  if (valor === null || valor === undefined) {
    return '';
  }

  // Evita enviar objetos como [object Object].
  if (typeof valor === 'object') {
    return '';
  }

  return String(valor);
};

const dinheiro = valor => {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return '';
  }

  const numero = Number(valor);

  if (!Number.isFinite(numero)) {
    return '';
  }

  return (numero / 100).toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
};

/* =========================================================
   NOME DO PAGANTE
========================================================= */

const extrairNome = boleto => {
  return texto(
    primeiroValor(
      boleto.customer_name,
      boleto.customer?.name,
      boleto.customer?.legal_name,
      boleto.payer?.name,
      boleto.payer?.legal_name
    )
  );
};

/* =========================================================
   DOCUMENTO DO CLIENTE
========================================================= */

const extrairDocumento = boleto => {
  const documento = primeiroValor(
    boleto.customer_document,
    boleto.customer?.document,
    boleto.payer?.document
  );

  if (
    documento === null ||
    documento === undefined ||
    documento === ''
  ) {
    return texto(
      primeiroValor(
        boleto.customer?.document_number,
        boleto.customer?.tax_id,
        boleto.payer?.document_number,
        boleto.payer?.tax_id
      )
    );
  }

  // Quando já é texto ou número.
  if (typeof documento !== 'object') {
    return String(documento);
  }

  // Quando o documento é devolvido como objeto.
  return texto(
    primeiroValor(
      documento.identity,
      documento.number,
      documento.document_number,
      documento.value,
      documento.tax_id,
      documento.cpf,
      documento.cnpj
    )
  );
};

/* =========================================================
   LINK DO BOLETO
========================================================= */

const extrairLinkBoleto = boleto => {
  const somenteLink = valor => {
    if (typeof valor !== 'string') {
      return '';
    }

    const link = valor.trim();

    return /^https?:\/\//i.test(link) ? link : '';
  };

  const procurarEmObjeto = objeto => {
    if (!objeto) return '';

    if (typeof objeto === 'string') {
      return somenteLink(objeto);
    }

    if (Array.isArray(objeto)) {
      for (const item of objeto) {
        const encontrado = procurarEmObjeto(item);

        if (encontrado) return encontrado;
      }

      return '';
    }

    if (typeof objeto !== 'object') {
      return '';
    }

    const camposPreferenciais = [
      'url',
      'payment_url',
      'pdf_url',
      'download_url',
      'bank_slip_url',
      'boleto_url',
      'invoice_url',
      'checkout_url',
      'link',
    ];

    for (const campo of camposPreferenciais) {
      const encontrado = somenteLink(objeto[campo]);

      if (encontrado) return encontrado;
    }

    for (const valor of Object.values(objeto)) {
      const encontrado = procurarEmObjeto(valor);

      if (encontrado) return encontrado;
    }

    return '';
  };

  const estruturas = [
    boleto.payment_options?.bank_slip,
    boleto.payment_options?.boleto,
    boleto.bank_slip,
    boleto.boleto,
    boleto.payment_options,
  ];

  for (const estrutura of estruturas) {
    const encontrado = procurarEmObjeto(estrutura);

    if (encontrado) return encontrado;
  }

  return primeiroValor(
    somenteLink(boleto.bank_slip_url),
    somenteLink(boleto.boleto_url),
    somenteLink(boleto.payment_url),
    somenteLink(boleto.invoice_url),
    somenteLink(boleto.pdf_url),
    somenteLink(boleto.download_url)
  );
};

/* =========================================================
   NOME DA COBRANCA E DESCRICAO

   A Cora devolve os dois dentro de "services", que so vem
   no detalhe do boleto (a listagem nao traz).
========================================================= */

const listaDeServicos = boleto => {
  const servicos = boleto.services || boleto.service;

  if (!servicos) {
    return [];
  }

  return Array.isArray(servicos) ? servicos : [servicos];
};

const juntarServicos = (boleto, campo) => {
  const valores = listaDeServicos(boleto)
    .map(servico => texto(servico && servico[campo]).trim())
    .filter(valor => valor !== '');

  // Um boleto pode ter mais de um servico: junta sem repetir.
  return Array.from(new Set(valores)).join(' | ');
};

const extrairNomeCobranca = boleto => {
  return texto(
    primeiroValor(
      juntarServicos(boleto, 'name'),
      boleto.name,
      boleto.service_name,
      boleto.code
    )
  );
};

const extrairDescricao = boleto => {
  return texto(
    primeiroValor(
      juntarServicos(boleto, 'description'),
      boleto.description,
      boleto.notes
    )
  );
};

/* =========================================================
   DATAS E DIAS VENCIDOS
========================================================= */

const dataUTC = valor => {
  if (!valor) return null;

  const partes = String(valor)
    .slice(0, 10)
    .split('-')
    .map(Number);

  if (
    partes.length !== 3 ||
    partes.some(numero => !Number.isFinite(numero))
  ) {
    return null;
  }

  const [ano, mes, dia] = partes;

  return Date.UTC(ano, mes - 1, dia);
};

const diasVencidos = boleto => {
  const status = String(boleto.status || '').toUpperCase();

  if (
    [
      'CANCELLED',
      'DRAFT',
      'RECURRENCE_DRAFT',
    ].includes(status)
  ) {
    return '';
  }

  const vencimentoTexto = primeiroValor(
    boleto.payment_terms?.due_date,
    boleto.due_date
  );

  const vencimento = dataUTC(vencimentoTexto);

  if (vencimento === null) {
    return '';
  }

  const dataPagamento = primeiroValor(
    boleto.paid_at,
    boleto.payment?.paid_at
  );

  let dataFinal;

  if (dataPagamento) {
    dataFinal = dataUTC(dataPagamento);

    if (dataFinal === null) {
      return '';
    }
  } else if (status === 'PAID') {
    // Evita calcular até hoje quando está pago,
    // mas a Cora não informou a data.
    return '';
  } else {
    const hoje = new Date();

    dataFinal = Date.UTC(
      hoje.getFullYear(),
      hoje.getMonth(),
      hoje.getDate()
    );
  }

  return Math.max(
    0,
    Math.floor(
      (dataFinal - vencimento) / 86400000
    )
  );
};

/* =========================================================
   MONTAGEM DAS COLUNAS A:Q
========================================================= */

const montarLinha = boleto => [
  // A — id
  texto(boleto.id),

  // B — status
  texto(boleto.status),

  // C — Criado em
  texto(boleto.created_at),

  // D — Valor Total
  dinheiro(boleto.total_amount),

  // E — Nome do Pagante
  extrairNome(boleto),

  // F — Documento do Cliente
  extrairDocumento(boleto),

  // G — Data do Vencimento
  texto(
    primeiroValor(
      boleto.payment_terms?.due_date,
      boleto.due_date
    )
  ),

  // H — Forma de pagamento
  texto(
    primeiroValor(
      boleto.payment_form,
      boleto.payment?.method,
      boleto.payment_method
    )
  ),

  // I — Data Pagamento
  texto(
    primeiroValor(
      boleto.paid_at,
      boleto.payment?.paid_at
    )
  ),

  // J — Total Pago
  dinheiro(
    primeiroValor(
      boleto.total_paid,
      boleto.payment?.total_paid
    )
  ),

  // K — Multa Aplicada
  dinheiro(
    primeiroValor(
      boleto.fine_paid,
      boleto.payment?.fine_paid
    )
  ),

  // L — Juros Aplicado
  dinheiro(
    primeiroValor(
      boleto.interest_paid,
      boleto.payment?.interest_paid
    )
  ),

  // M — Desconto Aplicado
  dinheiro(
    primeiroValor(
      boleto.discount_paid,
      boleto.payment?.discount_paid
    )
  ),

  // N — Boleto
  extrairLinkBoleto(boleto),

  // O — Dias vencidos
  diasVencidos(boleto),

  // P — Nome da Cobrança
  extrairNomeCobranca(boleto),

  // Q — Descrição
  //
  // P e Q foram inseridas na planilha antes do bloco do
  // SIGA, que passou a ocupar R ate Z. Por isso este fluxo
  // continua gravando um range contiguo (A ate Q) sem
  // encostar nas colunas de conciliacao.
  extrairDescricao(boleto),
];

/* =========================================================
   ATUALIZAR EXISTENTES E ADICIONAR NOVOS
========================================================= */

const atualizacoes = [];
const novasLinhas = [];

for (const boleto of itens) {
  const id = String(boleto.id || '').trim();

  if (!id) continue;

  const valores = montarLinha(boleto);
  const numeroLinha = linhaPorId.get(id);

  if (numeroLinha) {
    atualizacoes.push({
      range: `TodosBoletos!A${numeroLinha}:Q${numeroLinha}`,
      majorDimension: 'ROWS',
      values: [valores],
    });
  } else {
    novasLinhas.push(valores);
  }
}

/* =========================================================
   RESULTADO DO LOTE
========================================================= */

return [
  {
    json: {
      atualizacoes,
      novasLinhas,
      quantidadeAtualizada: atualizacoes.length,
      quantidadeNova: novasLinhas.length,
    },
  },
];
